import java.io.*;
import java.util.*;

public class C {

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String inputStr = reader.readLine();
        long number = Long.parseLong(inputStr);
        long output = processNumber(number);
        System.out.println(output);
    }

    static long[] ONES = new long[17];
    static {
        ONES[1] = 1;
        for (int i = 2; i < 17; i++) {
            ONES[i] = 10 * ONES[i - 1] + 1;
        }
    }

    static long processNumber(long x) {
        return computeCost(x, 16);
    }

    static long computeCost(long x, int len) {
        x = Math.abs(x);
        if (x % ONES[len] == 0) {
            return (x / ONES[len]) * len;
        }
        long lower = x / ONES[len];
        long upper = lower + 1;

        long costOption1 = lower * len + computeCost(x - lower * ONES[len], len - 1);
        long costOption2 = upper * len + computeCost(upper * ONES[len] - x, len - 1);
        return Math.min(costOption1, costOption2);
    }
}
